create type public.sanie_category_type as enum ('income','expense');
create type public.sanie_category_status as enum ('active','archived','deleted');
create type public.sanie_transaction_type as enum ('income','expense','transfer','goal_contribution');
create type public.sanie_goal_status as enum ('active','completed','paused');
create type public.sanie_karobar_type as enum ('lent','borrowed','returned','repaid','adjustment');
create type public.sanie_task_type as enum ('general','board_study');
create type public.sanie_task_status as enum ('pending','in_progress','completed');
create type public.sanie_priority as enum ('low','normal','high','urgent');

create table public.accounts (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(length(trim(name)) between 1 and 100), account_type text not null check(account_type in ('cash','bank','esewa','khalti','ime_pay','wallet','credit_card','savings','current')), account_number text, opening_balance numeric(15,2) not null default 0, balance numeric(15,2) not null default 0, currency char(3) not null default 'NPR' check(currency ~ '^[A-Z]{3}$'), color text, icon text, is_active boolean not null default true, is_default boolean not null default false, include_in_savings boolean not null default false, include_in_net_balance boolean not null default true, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.categories (id uuid primary key, user_id uuid references public.profiles(id) on delete cascade, name text not null check(length(trim(name)) between 1 and 100), category_type public.sanie_category_type not null, icon text, color text, description text, is_system boolean not null default false, status public.sanie_category_status not null default 'active', is_pinned boolean not null default false, sort_order integer not null default 999, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check ((is_system and user_id is null) or (not is_system and user_id is not null)));
create table public.subcategories (id uuid primary key, user_id uuid references public.profiles(id) on delete cascade, category_id uuid not null references public.categories(id) on delete restrict, name text not null check(length(trim(name)) between 1 and 100), icon text, description text, status public.sanie_category_status not null default 'active', sort_order integer not null default 0, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.goals (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(length(trim(name)) between 1 and 100), target_amount numeric(15,2) not null check(target_amount > 0), initial_amount numeric(15,2) not null default 0 check(initial_amount >= 0), current_amount numeric(15,2) not null default 0 check(current_amount >= 0), deadline date, icon text, color text, description text, status public.sanie_goal_status not null default 'active', version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.people (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(length(trim(name)) between 1 and 150), person_type text not null default 'person' check(person_type in ('person','friend','family','shop','vendor','business','other')), phone text, email text, address text, photo_path text, notes text, status text not null default 'active' check(status in ('active','archived')), version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.recurring_transactions (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, account_id uuid not null references public.accounts(id) on delete restrict, category_id uuid not null references public.categories(id) on delete restrict, subcategory_id uuid references public.subcategories(id) on delete restrict, amount numeric(15,2) not null check(amount > 0), transaction_type public.sanie_category_type not null, frequency text not null check(frequency in ('daily','weekly','bi_weekly','monthly','quarterly','yearly')), day_of_month smallint check(day_of_month between 1 and 31), day_of_week smallint check(day_of_week between 0 and 6), start_date date not null, end_date date, next_occurrence date, description text, notes text, is_active boolean not null default true, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check(end_date is null or end_date >= start_date));
create table public.transactions (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, account_id uuid references public.accounts(id) on delete restrict, from_account_id uuid references public.accounts(id) on delete restrict, to_account_id uuid references public.accounts(id) on delete restrict, category_id uuid references public.categories(id) on delete restrict, subcategory_id uuid references public.subcategories(id) on delete restrict, amount numeric(15,2) not null check(amount > 0), transaction_type public.sanie_transaction_type not null, payment_method text, karobar_transaction_id uuid, client_request_id uuid, transfer_parent_id uuid references public.transactions(id) on delete restrict, goal_id uuid references public.goals(id) on delete restrict, recurring_definition_id uuid references public.recurring_transactions(id) on delete restrict, recurring_occurrence_date date, version bigint not null default 1 check(version > 0), transaction_date date not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check(transaction_type <> 'transfer' or (from_account_id is not null and to_account_id is not null and from_account_id <> to_account_id)), check(transaction_type <> 'goal_contribution' or (goal_id is not null and account_id is not null)));
create table public.budgets (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, category_id uuid references public.categories(id) on delete restrict, subcategory_id uuid references public.subcategories(id) on delete restrict, name text not null check(length(trim(name)) between 1 and 100), amount numeric(15,2) not null check(amount > 0), period text not null default 'monthly' check(period in ('daily','weekly','monthly','yearly')), start_date date not null, end_date date not null, alert_threshold numeric(5,2) not null default 80 check(alert_threshold between 0 and 100), is_active boolean not null default true, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check(end_date >= start_date), check(subcategory_id is null or category_id is not null));
create table public.karobar_transactions (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, person_id uuid not null references public.people(id) on delete restrict, transaction_type public.sanie_karobar_type not null, amount numeric(15,2) not null check(amount > 0), account_id uuid references public.accounts(id) on delete restrict, expense_transaction_id uuid, income_transaction_id uuid, payment_method text, client_request_id uuid, version bigint not null default 1 check(version > 0), description text, transaction_date date not null, due_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
alter table public.transactions add constraint transactions_karobar_fk foreign key (karobar_transaction_id) references public.karobar_transactions(id) on delete restrict;
alter table public.karobar_transactions add constraint karobar_expense_fk foreign key (expense_transaction_id) references public.transactions(id) on delete restrict, add constraint karobar_income_fk foreign key (income_transaction_id) references public.transactions(id) on delete restrict;
create table public.tasks (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, task_type public.sanie_task_type not null default 'general', title text not null check(length(trim(title)) between 1 and 255), content text, category text, due_date date, display_date_bs char(10), subject text, unit_label text, status public.sanie_task_status not null default 'pending', completed_at timestamptz, priority public.sanie_priority not null default 'normal', reminder_at timestamptz, summary_url text, seed_key text, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.notifications (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, notification_type text not null, title text not null, message text, icon text, color text, priority public.sanie_priority not null default 'normal', reference_type text, reference_id uuid, is_read boolean not null default false, version bigint not null default 1 check(version > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.attachments (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, transaction_id uuid references public.transactions(id) on delete restrict, goal_id uuid references public.goals(id) on delete restrict, storage_bucket text not null, storage_object_path text not null, file_name text not null, file_size bigint check(file_size is null or file_size >= 0), mime_type text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check(transaction_id is not null or goal_id is not null), unique(storage_bucket, storage_object_path));
